import pickle
import json
from time import time

class SessionCache:
    def __init__(self, ttl=3600):
        self.cache = {}
        self.ttl = ttl
        self.timestamps = {}

    def set(self, key, user_object):
        """Store serialized user object with minimal overhead"""
        self.cache[key] = pickle.dumps(user_object)
        self.timestamps[key] = time()

    def get(self, key):
        """Retrieve and deserialize user object"""
        if key not in self.cache:
            return None

        if time() - self.timestamps[key] > self.ttl:
            del self.cache[key]
            del self.timestamps[key]
            return None

        # Fast path: deserialize directly from cache
        return pickle.loads(self.cache[key])

    def delete(self, key):
        if key in self.cache:
            del self.cache[key]
            del self.timestamps[key]

# Usage
cache = SessionCache()
user_data = {'id': 123, 'name': 'alice', 'role': 'admin'}
cache.set('session_abc123', user_data)
retrieved = cache.get('session_abc123')
print(retrieved)
